import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"AI Assistant — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Assistant — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/ai-assistant"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Assistant — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/ai-assistant"}]]},"headers":[],"relativePath":"user-guide/ai-assistant.md","filePath":"user-guide/ai-assistant.md","lastUpdated":1787431907000}'),r={name:"user-guide/ai-assistant.md"};function i(n,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-assistant-—-user-guide" tabindex="-1">AI Assistant — User Guide <a class="header-anchor" href="#ai-assistant-—-user-guide" aria-label="Permalink to &quot;AI Assistant — User Guide&quot;">​</a></h1><h2 id="who-can-use-it" tabindex="-1">Who can use it <a class="header-anchor" href="#who-can-use-it" aria-label="Permalink to &quot;Who can use it&quot;">​</a></h2><p>Your workspace must have the <strong>AI Assistant</strong> module installed from the Marketplace. Your role needs:</p><ul><li><strong><code>ai.use</code></strong> — chat, Lead Copilot, credit balance</li><li><strong><code>ai.confirm</code></strong> — approve tasks or other suggested writes</li><li><strong><code>ai.manage</code></strong> — configure workspace AI settings (Settings → AI tab and AI settings API)</li></ul><p>Without the module, AI menu items and API routes are hidden.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="business-chat" tabindex="-1">Business chat <a class="header-anchor" href="#business-chat" aria-label="Permalink to &quot;Business chat&quot;">​</a></h3><p>Ask EloSync about your permitted data — open tasks, stale leads, projects, sales pipeline, overdue invoices, and more. Answers respect your <strong>module entitlements</strong> and <strong>permissions</strong> (for example you only see leads you are allowed to view).</p><p>On an empty conversation, starter chips appear only when the matching module is installed <strong>and</strong> you have that module’s view permission. Citations link only to same-app record paths for modules you are entitled to.</p><p>Write actions (such as creating a task) appear as <strong>suggestions</strong> first. Nothing is saved until you <strong>confirm</strong>.</p><h3 id="lead-copilot" tabindex="-1">Lead Copilot <a class="header-anchor" href="#lead-copilot" aria-label="Permalink to &quot;Lead Copilot&quot;">​</a></h3><p>From a lead record, use Copilot actions:</p><ul><li><strong>Summarize</strong> — status, urgency, and recent activity themes</li><li><strong>Next action</strong> — single best follow-up with rationale</li><li><strong>Draft follow-up</strong> — copy-ready message (general, email, or WhatsApp tone)</li></ul><h3 id="credits-platform-mode" tabindex="-1">Credits (Platform mode) <a class="header-anchor" href="#credits-platform-mode" aria-label="Permalink to &quot;Credits (Platform mode)&quot;">​</a></h3><p>When your workspace uses <strong>Platform AI</strong> (default), each turn consumes credits from:</p><ol><li><strong>Included monthly allowance</strong> (from your AI subscription, prorated when you join mid-month)</li><li><strong>Prepaid packs</strong> (optional Marketplace add-ons — they roll over)</li></ol><p>Check <strong>Settings → AI</strong> or the credits panel for remaining balance. When credits run out, new messages return a payment-required notice until you add a pack or wait for the monthly refresh.</p><h3 id="bring-your-own-key-byok" tabindex="-1">Bring your own key (BYOK) <a class="header-anchor" href="#bring-your-own-key-byok" aria-label="Permalink to &quot;Bring your own key (BYOK)&quot;">​</a></h3><p>If your operator allows it, workspace admins can switch to <strong>BYOK</strong> mode and supply your own provider API key. Usage is billed by your provider directly; EloSync does not burn platform credits in BYOK mode.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Be specific — mention time ranges (“due today”, “stale 14 days”) for sharper tool use.</li><li>Confirm write suggestions promptly; pending actions expire after 24 hours.</li><li>Lead Copilot only accesses leads you can already open in the CRM.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/tenant-settings">Tenant settings — AI</a></li><li><a href="/user-guide/leads-overview">Leads</a></li><li><a href="/user-guide/tasks-overview">Tasks</a></li></ul>',23)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
